    // The only implementation, and the one the interface was copied from.
}

internal interface LoanSource {
    suspend fun loansDueBefore(day: LocalDate): List<Loan>
    suspend fun renew(id: String, until: LocalDate): RenewalOutcome
}

// Data layer: a gateway that forwards.
internal class LoanGateway(private val source: LoanSource) {
    suspend fun loansDueBefore(day: LocalDate): List<Loan> =
        source.loansDueBefore(day)
}

// Presentation model: one field per Loan field.
internal data class LoanSummary(
    val id: String,
    val title: String,
    val dueOn: LocalDate,
    val renewals: Int,
)

internal fun Loan.toSummary() = LoanSummary(id, title, dueOn, renewals)
